export const BODY: string = "\n<p>كل صورة تلتقطها تحفظ طبقة معلومات مخفية: ضبط الكاميرا وتاريخ الالتقاط وموديل الجهاز، وأحيانًا موقعك الدقيق، تسافر داخل الملف، غير مرئية في الصورة نفسها.</p>\n<p>عارض بيانات الصور الوصفية يقرأ تلك الطبقة المخفية ويُظهرها لك بلغة واضحة: يحوّل الترويسات الثنائية إلى تقرير مقروء تستطيع الاستفادة منه فعلًا.</p>\n<p>في هذا الدليل نشرح ما بيانات الصور الوصفية وما يكشفه العارض وكيف تستخدمه قبل مشاركة صورة: وسترى أيضًا مخاطر الخصوصية وتصدير JSON وكيف تتحقق من أن ملفًا نظيفًا نظيف فعلًا.</p>\n<h2 id=\"what-is-image-metadata\">ما بيانات الصور الوصفية؟</h2>\n<p>بيانات الصور الوصفية هي بيانات محفوظة داخل الملف، بجانب البكسلات: تصف الصورة بدل إظهارها، كملصق ملصوق على ظهر صورة مطبوعة.</p>\n<p>النوع الأكثر شيوعًا هو EXIF، اختصار Exchangeable Image File Format: الكاميرات والهواتف تكتب بيانات EXIF تلقائيًا في كل مرة تضغط فيها زر الغالق. وقد يشمل EXIF علامة الكاميرا وموديلها وبيانات العدسة والفتحة وسرعة الغالق وISO والبعد البؤري وحالة الفلاش والتاريخ والوقت الدقيقين اللذين التُقطت فيهما الصورة.</p>\n<p>وبيانات وصفية أخرى تعيش في أماكن مختلفة: ملفات PNG تحمل مقاطع نص بها المؤلف والبرنامج وتاريخ الإنشاء: وWebP قد تحفظ كتل EXIF وعلامات تحريك: وملفات JPEG تحمل تعليقات وملفات تعريف ألوان. ولا شيء من هذا يُرى عند النظر إلى الصورة: تحتاج عارضًا لرؤيته، ومعظم الناس لا يراجعه أبدًا: لهذا تسرب صور مشتركة عبر الإنترنت أكثر مما يتخيل أصحابها.</p>\n<h2 id=\"what-the-viewer-shows\">ماذا يُظهر لك العارض؟</h2>\n<p>اسحب صورة إلى العارض فيحلل بايتات الملف على جهازك: وفي لحظة تحصل على ملخص وإشعار مخاطر خصوصية وجدول مجمع بكل حقل وجده.</p>\n<p>الملخص يُظهر صيغة الملف والأبعاد بالبكسلات والحجم: ويخبرك أيضًا إن وجد أي نوع من وسوم البيانات الوصفية الحساسة. ويجمع الجدول الإدخالات لتستطيع مراجعتها بسرعة: حقول الكاميرا معًا وحقول تعريض EXIF معًا وحقول GPS معًا، ومقاطع PNG أو WebP لها مجموعتها الخاصة.</p>\n<p>والحقول الحساسة تحمل وسمًا كهرمانيًا يقول Privacy Tag: أمثلة نموذجية: إحداثيات GPS وطوابع زمنية دقيقة وأسماء مصورين وأرقام تسلسلية للكاميرا وسلاسل بها اسم جهازك.</p>\n<p>وإذا وُجدت بيانات GPS، يبرز مربع إشعار خط العرض وخط الطول الدقيقين مفكوكين أصلًا: ويقدم أيضًا قفزة بنقرة واحدة إلى أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a>، لتستطيع تنظيف الملف.</p>\n<h2 id=\"exif-fields-explained\">حقول EXIF موضحة</h2>\n<p>يُنظم EXIF في أدلة تسمى IFD: يقرأ العارض جداول TIFF IFD0 وExifIFD وGPSIFD من ملفات JPEG، إضافة إلى كتل eXIf في PNG ومقاطع EXIF في WebP.</p>\n<p>IFD0 يحفظ بيانات الصورة والجهاز الأساسية: هنا تعيش علامة الكاميرا وموديلها، مع البرنامج الذي عدّل الملف آخر مرة وأي ملاحظة حقوق نشر. وExifIFD يحفظ قياسات التعريض المسجلة عند التقاط الصورة: سرعة الغالق والفتحة وISO والبعد البؤري ووضع القياس وحالة الفلاش تعيش في هذا الدليل.</p>\n<p>وGPSIFD يحفظ بيانات الموقع كأرقام كسرية: يحوّل العارض درجات ودقائق وثوانٍ إلى خط عرض وخط طول عشريين تلقائيًا، فتستطيع قراءة الإحداثيات مباشرة. وليست كل الحقول تظهر في كل صورة: لقطة شاشة ليس لها بيانات كاميرا، وصورة منزلة من تطبيق مراسلة غالبًا ليس لها EXIF، لأن التطبيق أزاله.</p>\n<p>وعندما يغيب حقل، فذلك أيضًا معلومات مفيدة: يخبرك أن الملف عُولج أصلًا، أو أنه لم يكن أصل الكاميرا أبدًا.</p>\n<h2 id=\"gps-and-privacy\">بيانات GPS والخصوصية</h2>\n<p>إحداثيات GPS هي أكثر ما قد تحمله صورة حساسية: زوج واحد من الأرقام قد يشير إلى منزلك أو عملك أو مدرسة طفلك أو المكان الدقيق الذي التُقطت فيه الصورة.</p>\n<p>الهواتف تسجل بيانات GPS افتراضيًا في معظم تطبيقات الكاميرا: تُحفظ الإحداثيات بصمت، ولا شيء في الصورة نفسها يلمح إلى وجودها. ومشاركة صورة دون تنظيف عبر الإنترنت قد تكشف موقعك لأي شخص ينزلها ويفتحها في عارض بيانات وصفية: ذلك يشمل غرباء في متاجر عبر الإنترنت ومنتديات ووسائل تواصل اجتماعي.</p>\n<p>والعارض يجعل هذا الخطر مرئيًا: عندما توجد وسوم GPSIFD، يظهر إشعار كهرماني \"GPS Location Coordinates Detected\" فوق جدول الخصائص مباشرة، مع الإحداثيات مفكوكة. والمراجعة قبل النشر تستغرق ثوانٍ: وإذا ظهرت إحداثيات، أزلها بأداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a> قبل أن تصل الصورة إلى أي مكان عام.</p>\n<h2 id=\"png-and-webp-chunks\">ترويسات PNG وWebP التقنية</h2>\n<p>JPEG يأخذ معظم الانتباه، لكن ملفات PNG وWebP تحمل أيضًا بياناتها الوصفية الخاصة: يقرأ العارض هذه المقاطع التقنية لكي لا يبقى شيء مخفيًا.</p>\n<p>في ملفات PNG يقرأ مقطع IHDR، الذي يحفظ عمق البت ونوع اللون: ويقرأ أيضًا pHYs، المقطع الذي يحفظ كثافة البكسلات المادية للطباعة أو ضبط التصميم. ومقاطع نص PNG مهمة أيضًا للخصوصية: مقاطع tEXt وiTXt قد تحفظ أسماء برامج وأسماء مؤلفين وتعليقات وتواريخ إنشاء: ومقطع tIME يحفظ وقت آخر تعديل.</p>\n<p>وفي ملفات WebP، يقرأ العارض علامات VP8X، التي تُظهر إن كانت الصورة لها قناة ألفا أو تحريك: وتُفك مقاطع EXIF في WebP بجانبها، فبيانات كاميرا WebP تُقرأ أيضًا. ويبلغ العارض أيضًا عن الصيغة الحقيقية للملف بفحص البايتات السحرية الثنائية لا الاسم: PNG معاد تسميته بامتداد .jpg ما زال يُبلغ عنه كـPNG.</p>\n<h2 id=\"how-to-use-the-viewer\">كيف تستخدم العارض</h2>\n<p>استخدام العارض يستغرق خمس خطوات، ولا واحدة تحتاج حسابًا ولا رفع ملفات: كل شيء يحدث على جهازك.</p>\n<p>والعارض للقراءة فقط بصرامة: يقرأ الترويسات من ذاكرة المتصفح ليعرض لك ما بداخلها، دون تغيير أو ضغط أو حذف أي شيء من ملفك الأصلي.</p>\n<p>وتستطيع مراجعة ملفات واحدًا تلو الآخر دون تحديث الصفحة: انقر أيقونة سلة المهملات الحمراء في شريط الملخص للعودة إلى منطقة الرفع ثم اسحب الصورة التالية.</p>\n<ol>\n<li>اسحب صورة أو اخترها لمراجعتها: تُقبل ملفات JPG وPNG وWebP وHEIC وGIF وBMP وSVG حتى 20 MB، أو الصق بـCtrl+V.</li>\n<li>راجع الملخص وإشعار مخاطر الخصوصية في الأعلى: يُظهر الصيغة والأبعاد وحجم الملف وإن وُجدت وسوم حساسة.</li>\n<li>راجع أي تنبيه موقع GPS: إذا وُجدت إحداثيات، يُظهر مربع الإشعار خط العرض وخط الطول الدقيقين.</li>\n<li>استكشف جدول البيانات الوصفية المستخرجة: الإدخالات مجمعة حسب الكاميرا وEXIF وGPS ومقاطع PNG أو WebP ومعلومات الملف، مع وسوم Privacy Tag كهرمانية في الحقول الحساسة.</li>\n<li>انسخ JSON أو صدّره، أو أزل الوسوم: انقر \"نسخ JSON\" للتقرير الكامل، أو \"تصدير JSON\" لحفظ ملف .json، أو \"إزالة البيانات الوصفية\" لتنظيف الملف.</li>\n</ol>\n<h2 id=\"json-export\">نسخ تقارير JSON وتصديرها</h2>\n<p>أحيانًا تحتاج البيانات الوصفية في شكل تستطيع حفظه أو مشاركته أو لصقه في تقرير خطأ: يصدّر العارض التقرير الكامل المحلل كـJSON منظم.</p>\n<p>انقر \"نسخ JSON\" في شريط الملخص لنقل تقرير ImageMetadataReport كله إلى حافظتك: يبقى جاهزًا للصق في وثيقة أو تذكرة أو رسالة محادثة. وانقر \"تصدير JSON\" لتنزيل ملف باسم صورتك ولاحقة _metadata: يستخدم المطورون هذه التقارير لتصحيح سير عمل الصور وتوثيق سلوك المعالجة.</p>\n<p>ويشمل JSON كل حقل فككه العارض، مجمعًا مثل الجدول على الشاشة: ذلك يسهل مقارنة ملفين، أو حفظ سجل لما احتواه ملف قبل تنظيفه.</p>\n<p>ولجولة عملية في خطوات الفحص، اقرأ <a href=\"/ar/blog/kayfiyya-ard-bayanat-as-sura/\">كيف ترى البيانات الوصفية لصورة</a>. ولمعرفة ما تكشفه الحقول عنك، اقرأ <a href=\"/ar/blog/bayanat-exif-mashruha/\">بيانات EXIF موضحة: ما تكشفه صورك</a>.</p>\n<h2 id=\"verifying-clean-files\">كيف تتحقق من ملف نظيف</h2>\n<p>من أكثر مهام عارض البيانات الوصفية فائدة مراجعة عمل شخص آخر: بعد تنظيف صورة، أعد سحب الملف النظيف إلى العارض لتأكيد اختفاء الوسوم.</p>\n<p>إذا نجح التنظيف، يؤكد إشعار أخضر أنه لم تُكتشف وسوم EXIF أو GPS أو كاميرا مخفية، ولا يظهر أي تنبيه GPS: إنها مراجعة حقيقية لبايتات الملف، لا مجرد تأكيد. وهذا مهم لأن بعض الأدوات تقول إنها تزيل بيانات وصفية لكنها تترك مقاطع خلفها: كتلة نص tEXt في PNG أو تعليق JPEG قد ينجو من منظف مهمل: ويكتشفها العارض.</p>\n<p>اجعل التحقق عادة مع الصور الحساسة: راجع ونظف وأعد المراجعة: والمراجعة الثانية تستغرق ثوانٍ وتثبت أن الخطوة الأولى نجحت.</p>\n<p>وإذا أظهر الملف النظيف وسومًا ما زالت، جرّب خيار Full Canvas Re-encode في أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a>: يعيد بناء البكسلات من الصفر، ما يزيل كل مقطع ثنائي موروث.</p>\n<h2 id=\"when-to-check-metadata\">متى تراجع البيانات الوصفية لصورة</h2>\n<p>راجع البيانات الوصفية في كل مرة تغادر فيها صورة تخزينك الخاص: الخطر ليس الصورة نفسها، بل من يستطيع تنزيلها وما يستطيع قراءته منها.</p>\n<p>المصورون يراجعون البيانات الوصفية لسبب آخر: ضبط تعريض لقطة عظيمة وصفة تستحق الحفظ، والعارض يقرأ ISO والفتحة وسرعة الغالق. والمطورون يراجعونها عندما تتصرف صور بغرابة: علامة اتجاه خطأ أو قيمة DPI غير متوقعة أو ملف ألوان مخفي غالبًا يفسر خطأ عرض.</p>\n<ul>\n<li>قبل النشر في إعلان بيع، حيث ينزل المشترون صورًا بدقة كاملة.</li>\n<li>قبل مشاركة صور عائلية في وسائل التواصل الاجتماعي، خاصة صور ملتقطة في المنزل أو المدرسة.</li>\n<li>قبل إرسال صور إلى صحفي أو عميل أو غريب قد يعيد إرسالها.</li>\n<li>قبل نشر صور في مدونة أو موقع، حيث تبقى الملفات قابلة للتنزيل لسنوات.</li>\n<li>بعد استلام صورة، لمعرفة متى وأين التُقطت وبأي كاميرا.</li>\n<li>عند تصحيح سير عمل صور، لرؤية أي حقول تنجو من كل خطوة معالجة.</li>\n</ul>\n<h2 id=\"viewer-limits\">ما لا يستطيع العارض فعله</h2>\n<p>العارض صادق بشأن حدوده: محلله العميق للمقاطع الثنائية مصمم لحاويات JPEG وPNG وWebP أصليًا في JavaScript، وتلك الصيغ الثلاث تحصل على أعمق قراءة.</p>\n<p>لملفات HEIC وGIF وBMP وSVG، يبلغ العارض عن معلومات حاوية موثوقة وحجم الملف والأبعاد بالبكسلات: ومقاطع EXIF الثنائية الكاملة لا تُستخرج في تلك الصيغ. ولقطات الشاشة الملصوقة غالبًا لا تُظهر وسوم كاميرا: حافظات نظام التشغيل تمرر خرائط بت خام بدل ملفات الكاميرا الأصلية.</p>\n<p>وصور منزلة من WhatsApp أو إنستغرام تُظهر صفر وسوم EXIF لسبب مشابه: وسائل التواصل الاجتماعي وتطبيقات المراسلة تزيل ترويسات EXIF والكاميرا وGPS تلقائيًا. وحد 20 MB لكل ملف يغطي JPEG كاميرات DSLR بدقة كاملة وتصديرات PNG مفصلة وملفات BMP دون ضغط: والملفات الأكبر يجب ضغطها أولًا، بـ<a href=\"/ar/\">ضاغط الصور</a> مثلًا.</p>\n<h2 id=\"metadata-on-mobile\">مراجعة البيانات الوصفية على الهاتف</h2>\n<p>معظم الصور تُلتقط بالهاتف، فالعارض يعمل أيضًا في متصفحات الهاتف: افتح الصفحة في Safari للهاتف أو Chrome واختر صورة مباشرة من معرضك.</p>\n<p>تستطيع مراجعة إحداثيات GPS مخفية وتفاصيل كاميرا على هاتفك قبل نشر صور عبر الإنترنت: تلك هي اللحظة التي تهم فيها المراجعة أكثر، لأن النشر يحدث من الهاتف دائمًا تقريبًا. والواجهة نفسها كما على الحاسوب: إشعار الملخص وتنبيه GPS والجدول المجمع تظهر بالتساوي، وإجراءا \"نسخ JSON\" و\"إزالة البيانات الوصفية\" يعملان بنفس الطريقة.</p>\n<p>وإذا وجدت بيانات GPS في صورة هاتف، أزلها قبل مشاركتها: أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a> تعمل أيضًا على الهاتف، فسير المراجعة والتنظيف كله يناسب جيبك.</p>\n<h2 id=\"metadata-viewer-summary\">في الخلاصة</h2>\n<p>بيانات الصور الوصفية هي البيانات المخفية داخل كل صورة: ضبط كاميرا وطوابع زمنية وملاحظات برامج، وأحيانًا إحداثيات GPS: والعارض يجعلها مرئية.</p>\n<p>راجع أي صورة قبل أن تصبح عامة، خاصة ملتقطة في المنزل أو المدرسة أو العمل: ابحث عن تنبيه GPS أولًا ثم راجع وسوم Privacy Tag الكهرمانية. وصدّر JSON عندما تحتاج سجلًا، وتحقق من الملفات النظيفة بإعادة مراجعتها: العارض مجاني ولا يطلب تسجيلًا ولا يرفع صورك أبدًا إلى أي مكان.</p>\n<p>ابدأ بـ<a href=\"/ar/arid-bayanat-as-sura/\">عارض البيانات الوصفية</a>، وعندما يحتاج ملف تنظيفًا، انتقل مباشرة إلى أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a>: يجب أن تُظهر صورك للعالم فقط ما قررت مشاركته، ولا شيء أكثر.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما الفرق بين بيانات EXIF وXMP وIPTC الوصفية؟","answer":"EXIF بيانات تكتبها الكاميرا، مثل ضبط التعريض والطوابع الزمنية وإحداثيات GPS: وXMP حزمة XML من Adobe قد تحفظ سجل تعديل وتقييمات وأوصافًا. وIPTC بيانات صحفية مثل التسميات وحقوق النشر."},{"question":"هل يستطيع عارض بيانات وصفية إخباري أين التُقطت صورة؟","answer":"نعم، إذا احتوت الصورة إحداثيات GPS: يفك العارض وسوم GPSIFD إلى خط عرض وخط طول عشريين ويعرضها في إشعار تحذير. وبدون وسوم GPS، لا يستطيع العارض تخمين موقع: يقرأ فقط ما في الملف."},{"question":"هل يعمل العارض مع صور ملتقطة بكاميرا DSLR أو بلا مرآة؟","answer":"نعم، كاميرات DSLR وبلا مرآة تكتب بيانات EXIF كاملة جدًا، بما فيها موديل العدسة والبعد البؤري والفتحة وسرعة الغالق وISO ووضع القياس: ويفك العارض كل ذلك ويعرضه في الجدول المجمع."},{"question":"لماذا تُظهر بعض صوري بيانات وصفية وأخرى لا تُظهر شيئًا؟","answer":"الملفات الأصلية من معرضك تحافظ على كل البيانات الوصفية: وصور مرت عبر WhatsApp أو إنستغرام أو فيسبوك أو بريد غالبًا تصل نظيفة، لأن تلك الخدمات تزيل ترويسات EXIF وGPS عند الرفع."},{"question":"هل مراجعة صورة خاصة في عارض بيانات وصفية عبر الإنترنت آمنة؟","answer":"يعتمد على الأداة: هذا العارض يحلل بايتات الملف محليًا في متصفحك، فصفر بايت يغادر جهازك: لا يُرفع شيء إلى خادم. وتجنب عارضات تطلب رفع الملف، لأن نسخة من صورتك تبقى على خادمها."},{"question":"هل أستطيع استخدام العارض لمراجعة صورة أرسلها لي شخص آخر؟","answer":"نعم، احفظ الصورة واسحبها إلى العارض واقرأ الجدول المجمع: تستطيع رؤية متى التُقطت وبأي كاميرا وإن حملت إحداثيات GPS. وتذكر أن ملفًا نظيفًا لا يُظهر شيئًا: ذلك يثبت فقط أن وسومه أُزيلت في نقطة ما."}];
